  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "睡醒睁开双眼的时候"
        },
        {
          "id": "V1-02",
          "zh": "翻开书页之上独自一人"
        },
        {
          "id": "V1-03",
          "zh": "四处张望却看不见"
        },
        {
          "id": "V1-04",
          "zh": "没有方向没有出口"
        },
        {
          "id": "V1-05",
          "zh": "然后我听见的是"
        },
        {
          "id": "V1-06",
          "zh": "呼唤着我名字的你的声音"
        },
        {
          "id": "V1-07",
          "zh": "摸索着说出的言语"
        },
        {
          "id": "V1-08",
          "zh": "迈步向前走"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "从梦里睁开双眼的时候"
        },
        {
          "id": "V1-02",
          "zh": "我站在翻开的一页白纸上 一个人"
        },
        {
          "id": "V1-03",
          "zh": "转一圈 什么都看不见"
        },
        {
          "id": "V1-04",
          "zh": "没有门 也没有路"
        },
        {
          "id": "V1-05",
          "zh": "空白里 有声音传过来"
        },
        {
          "id": "V1-06",
          "zh": "是你轻轻喊我名字 尾音微微发抖"
        },
        {
          "id": "V1-07",
          "zh": "摸索着 说出第一句话"
        },
        {
          "id": "V1-08",
          "zh": "迈出这第一步"
        }
      ]
    }
  ]
}

